/**
 ******************************************************************************
 * @file    test_fx_pipe.c
 * TEAM CODE (owner: Jack - audio input and SD storage) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Jack's storage subsystem (best-ui), with an AI coding assistant;
 *          Brendon (integrator) made effect-file jobs resumable, exactly or by a rebuild with a pre-roll (30 Oct 2026, with an AI coding assistant).
 * @brief   Host tests for fx_pipe.c: every source sample goes out exactly
 *          once, and everything that comes back is written before DONE.
 *
 * Each test runs a whole job through run_pipe(), which plays the parts of
 * the card and of FxRenderTask: a READ always gets what it asked for, and a
 * SEND is answered with the output length the real renderer gives for a
 * 32 kHz source (96 output samples per 64 in, 3/2 of a partial block).
 *
 * Groups:
 *   1. Sizes: 0, 1, 63, 64, 511, 512, 8191, 8192, 320 000 and 320 001
 *      samples are sent whole and written whole
 *   2. Chunks: multiples of 64 except the last; FIRST and LAST once each
 *   3. Card I/O: no write over 16 KB; a read while a chunk is out
 *   4. Progress: 0 to 100, never down
 *   5. Carrying on (fxp_continue): a parked job's pipe sends the rest once,
 *      with no FIRST, and writes the rest whole
 *   6. Rebuilding (fxp_rebuild): FIRST at the pre-roll's start, RESTORE once
 *      at the resume point (none from 0), the pre-roll's output thrown
 *      away, the rest written whole, the percentage never below the resume
 *      point
 ******************************************************************************/
#include "unity.h"
#include "fx_pipe.h"
#include <string.h>

void setUp(void) {}
void tearDown(void) {}

#define PIPE_MAX_ACTIONS 100000U    /* a job that needs more actions than this is stuck: the test fails */

/* What one simulated job did. */
typedef struct {
    uint32_t sent;               /* source samples sent */
    uint32_t chunks;             /* requests sent */
    uint32_t first_flags;        /* chunks with FXP_FLAG_FIRST */
    uint32_t last_flags;         /* chunks with FXP_FLAG_LAST */
    uint32_t restore_flags;      /* chunks with FXP_FLAG_RESTORE */
    uint32_t first_at;           /* the source sample the FIRST chunk started at */
    uint32_t restore_at;         /* ... and the RESTORE chunk */
    uint32_t sent_from;          /* the source sample the first chunk sent started at */
    uint32_t kept_replies;       /* replies fxp_reply_kept said were kept */
    uint32_t odd_chunks;         /* chunks not a multiple of 64 that were not the last */
    uint32_t replied_out;        /* output samples that came back */
    uint32_t written;            /* output samples written */
    uint32_t biggest_write;      /* the largest single write, in samples */
    uint32_t reads_while_out;    /* reads done while a chunk was out */
    uint32_t writes_while_out;   /* writes done while a chunk was out */
    uint32_t actions;
    bool     percent_went_down;
    uint8_t  percent_at_done;    /* fxp_percent when DONE was reached */
    bool     done;
} pipe_run_t;

/* The output length of the real renderer for n samples of a 32 kHz source. */
static uint32_t output_for(uint32_t n)
{
    return 96U * (n / 64U) + (3U * (n % 64U)) / 2U;
}

/* Run the pipe p (already begun or continued) to DONE, playing the card and
 * FxRenderTask. The percentage must never drop below where it started. */
static void drive_pipe(fx_pipe_t *p, pipe_run_t *run)
{
    memset(run, 0, sizeof(*run));
    run->sent_from = p->src_sent;
    uint32_t chunk_out = 0U;          /* the chunk that is out, waiting for its reply */
    uint8_t last_percent = fxp_percent(p);
    while (run->actions < PIPE_MAX_ACTIONS)
    {
        run->actions++;
        const fxp_action_t a = fxp_next(p);
        if (a == FXP_DONE)
        {
            run->done = true;
            run->percent_at_done = fxp_percent(p);
            return;
        }
        if (a == FXP_READ)
        {
            if (p->inflight) run->reads_while_out++;
            fxp_did_read(p, fxp_read_size(p));
        }
        else if (a == FXP_SEND)
        {
            uint8_t flags = 0U;
            const uint32_t n = fxp_chunk(p, &flags);
            const bool last = (flags & FXP_FLAG_LAST) != 0U;
            if (flags & FXP_FLAG_FIRST)
            {
                run->first_flags++;
                run->first_at = p->src_sent;
            }
            if (flags & FXP_FLAG_RESTORE)
            {
                run->restore_flags++;
                run->restore_at = p->src_sent;
            }
            if (last) run->last_flags++;
            if (!last && (n % FXP_BLOCK_SAMPLES) != 0U) run->odd_chunks++;
            run->sent += n;
            run->chunks++;
            chunk_out = n;
            fxp_did_send(p, n);
        }
        else if (a == FXP_WAIT)
        {
            /* FxRenderTask answers: the output of the chunk that was out. */
            const uint32_t n_out = output_for(chunk_out);
            run->replied_out += n_out;
            if (fxp_reply_kept(p)) run->kept_replies++;
            fxp_did_reply(p, n_out);
        }
        else
        {
            const uint32_t n = fxp_write_size(p);
            if (p->inflight) run->writes_while_out++;
            if (n > run->biggest_write) run->biggest_write = n;
            run->written += n;
            fxp_did_write(p, n);
        }
        const uint8_t percent = fxp_percent(p);
        if (percent < last_percent) run->percent_went_down = true;
        last_percent = percent;
    }
}

static void run_pipe(uint32_t src_samples, pipe_run_t *run)
{
    fx_pipe_t p;
    fxp_begin(&p, src_samples);
    drive_pipe(&p, run);
}

/* Every sample sent once, everything that came back written, DONE reached. */
static void check_whole(uint32_t src_samples)
{
    pipe_run_t run;
    run_pipe(src_samples, &run);
    TEST_ASSERT_TRUE_MESSAGE(run.done, "the job never reached DONE");
    TEST_ASSERT_EQUAL_UINT32(src_samples, run.sent);
    TEST_ASSERT_EQUAL_UINT32(output_for(src_samples), run.replied_out);
    TEST_ASSERT_EQUAL_UINT32(run.replied_out, run.written);
    TEST_ASSERT_EQUAL_UINT32(0U, run.odd_chunks);
    TEST_ASSERT_TRUE(run.biggest_write <= FXP_STAGE_OUT_SAMPLES);
}

/* ---------- 1. Sizes ---------- */

void test_zero_samples_is_done_at_once_and_sends_nothing(void)
{
    fx_pipe_t p;
    fxp_begin(&p, 0U);
    TEST_ASSERT_EQUAL(FXP_DONE, fxp_next(&p));
    TEST_ASSERT_EQUAL_UINT8(100U, fxp_percent(&p));
    pipe_run_t run;
    run_pipe(0U, &run);
    TEST_ASSERT_EQUAL_UINT32(0U, run.chunks);
    TEST_ASSERT_EQUAL_UINT32(0U, run.last_flags);
}

void test_one_sample_is_sent_as_the_first_and_last_chunk(void)
{
    pipe_run_t run;
    run_pipe(1U, &run);
    check_whole(1U);
    TEST_ASSERT_EQUAL_UINT32(1U, run.chunks);
    TEST_ASSERT_EQUAL_UINT32(1U, run.first_flags);
    TEST_ASSERT_EQUAL_UINT32(1U, run.last_flags);
}

void test_exactly_one_chunk_is_one_request(void)
{
    pipe_run_t run;
    run_pipe(FXP_CHUNK_IN, &run);
    check_whole(FXP_CHUNK_IN);
    TEST_ASSERT_EQUAL_UINT32(1U, run.chunks);
}

void test_one_sample_more_than_a_chunk_makes_two_chunks(void)
{
    pipe_run_t run;
    run_pipe(FXP_CHUNK_IN + 1U, &run);
    check_whole(FXP_CHUNK_IN + 1U);
    TEST_ASSERT_EQUAL_UINT32(2U, run.chunks);
}

void test_a_ten_second_recording_is_sent_whole_and_written_whole(void)
{
    check_whole(320000U);                              /* 10 s at 32 kHz */
    pipe_run_t run;
    run_pipe(320000U, &run);
    TEST_ASSERT_EQUAL_UINT32(625U, run.chunks);        /* 320 000 / 512 */
    TEST_ASSERT_EQUAL_UINT32(480000U, run.written);    /* 10 s at 48 kHz */
}

void test_an_odd_sample_count_is_sent_whole(void)
{
    static const uint32_t sizes[] = { 63U, 64U, 511U, 8191U, 8192U, 320001U };
    for (size_t i = 0U; i < (sizeof(sizes) / sizeof(sizes[0])); i++)
    {
        check_whole(sizes[i]);
    }
}

/* ---------- 2. Chunks ---------- */

void test_chunks_are_multiples_of_64_except_the_last(void)
{
    static const uint32_t sizes[] = { 1U, 63U, 64U, 511U, 512U, 8191U, 8192U, 320000U, 320001U };
    for (size_t i = 0U; i < (sizeof(sizes) / sizeof(sizes[0])); i++)
    {
        pipe_run_t run;
        run_pipe(sizes[i], &run);
        TEST_ASSERT_EQUAL_UINT32(0U, run.odd_chunks);
    }
}

void test_last_flag_is_set_once_for_every_size_above_zero(void)
{
    static const uint32_t sizes[] = { 1U, 63U, 64U, 511U, 512U, 8191U, 8192U, 320000U, 320001U };
    for (size_t i = 0U; i < (sizeof(sizes) / sizeof(sizes[0])); i++)
    {
        pipe_run_t run;
        run_pipe(sizes[i], &run);
        TEST_ASSERT_EQUAL_UINT32(1U, run.last_flags);
    }
}

void test_first_flag_is_set_once(void)
{
    static const uint32_t sizes[] = { 1U, 512U, 8192U, 320001U };
    for (size_t i = 0U; i < (sizeof(sizes) / sizeof(sizes[0])); i++)
    {
        pipe_run_t run;
        run_pipe(sizes[i], &run);
        TEST_ASSERT_EQUAL_UINT32(1U, run.first_flags);
    }
}

/* ---------- 3. Card I/O ---------- */

void test_writes_never_exceed_16_kb(void)
{
    pipe_run_t run;
    run_pipe(320001U, &run);
    TEST_ASSERT_TRUE(run.biggest_write > 0U);
    TEST_ASSERT_TRUE(run.biggest_write * 2U <= 16384U);
}

void test_reads_and_writes_happen_while_a_chunk_is_out(void)
{
    pipe_run_t run;
    run_pipe(320000U, &run);
    TEST_ASSERT_TRUE(run.reads_while_out > 0U);        /* the next 8 KB is read under the DSP time */
    TEST_ASSERT_TRUE(run.writes_while_out > 0U);       /* and a full stage_out is written under it */
}

/* ---------- 4. Progress ---------- */

void test_percent_climbs_to_100_and_never_drops(void)
{
    fx_pipe_t p;
    fxp_begin(&p, 320000U);
    TEST_ASSERT_EQUAL_UINT8(0U, fxp_percent(&p));
    pipe_run_t run;
    run_pipe(320000U, &run);
    TEST_ASSERT_FALSE(run.percent_went_down);
    TEST_ASSERT_EQUAL_UINT8(100U, run.percent_at_done);
}

/* ---------- 5. Carrying on (TEAM CODE, written by Brendon, 30 Oct 2026) ---------- */

/* A job parked at source sample `at` (a chunk edge) carries on: only the
 * rest is sent, with no FIRST (FxRenderTask still has the job's state) and
 * one LAST, and the rest of the output is written whole. */
void test_continue_sends_the_rest_once_with_no_first(void)
{
    static const uint32_t points[] = { 512U, 4096U, 4608U, 160256U, 319488U };
    for (size_t i = 0U; i < (sizeof(points) / sizeof(points[0])); i++)
    {
        const uint32_t total = 320001U;
        const uint32_t at = points[i];
        fx_pipe_t p;
        fxp_continue(&p, total, at, output_for(at));
        TEST_ASSERT_EQUAL(FXP_READ, fxp_next(&p));               /* the input after `at` is read again */
        TEST_ASSERT_EQUAL_UINT8((uint8_t)(((uint64_t)at * 100U) / total), fxp_percent(&p));
        pipe_run_t run;
        drive_pipe(&p, &run);
        TEST_ASSERT_TRUE(run.done);
        TEST_ASSERT_EQUAL_UINT32(total - at, run.sent);
        TEST_ASSERT_EQUAL_UINT32(0U, run.first_flags);
        TEST_ASSERT_EQUAL_UINT32(1U, run.last_flags);
        TEST_ASSERT_EQUAL_UINT32(0U, run.odd_chunks);
        TEST_ASSERT_EQUAL_UINT32(output_for(total) - output_for(at), run.written);
        TEST_ASSERT_EQUAL_UINT32(output_for(total), p.out_written);     /* the whole file's count */
        TEST_ASSERT_FALSE(run.percent_went_down);
        TEST_ASSERT_EQUAL_UINT8(100U, run.percent_at_done);
    }
}

/* Parked in J_CLOSE or J_RENAME: everything was sent and written. */
void test_continue_at_the_end_is_done_at_once(void)
{
    fx_pipe_t p;
    fxp_continue(&p, 32000U, 32000U, output_for(32000U));
    TEST_ASSERT_EQUAL(FXP_DONE, fxp_next(&p));
    TEST_ASSERT_EQUAL_UINT8(100U, fxp_percent(&p));
    TEST_ASSERT_EQUAL_UINT32(output_for(32000U), p.out_written);
}

/* ---------- 6. Rebuilding (TEAM CODE, written by Brendon, 30 Oct 2026) ---------- */

/* A rebuild at `at` from `from`: the source is read again from `from`; FIRST
 * goes with the chunk at `from`, RESTORE once with the chunk at `at`, LAST
 * once at the end; only the output from `at` on is written, and it is
 * exactly what that part of the source gives. */
void test_rebuild_sends_first_at_from_restore_once_at_the_resume_point_and_last_at_the_end(void)
{
    static const uint32_t cases[][2] = {        /* { from, at } */
        { 512U, 4096U }, { 2048U, 4608U }, { 4096U, 8192U }, { 47104U, 175616U }, { 315392U, 319488U },
    };
    for (size_t i = 0U; i < (sizeof(cases) / sizeof(cases[0])); i++)
    {
        const uint32_t total = 320001U;
        const uint32_t from = cases[i][0];
        const uint32_t at = cases[i][1];
        fx_pipe_t p;
        fxp_rebuild(&p, total, from, at, output_for(at));
        TEST_ASSERT_EQUAL(FXP_READ, fxp_next(&p));
        TEST_ASSERT_EQUAL_UINT32(from, p.src_read);                     /* reads start at the pre-roll */
        pipe_run_t run;
        drive_pipe(&p, &run);
        TEST_ASSERT_TRUE(run.done);
        TEST_ASSERT_EQUAL_UINT32(from, run.sent_from);
        TEST_ASSERT_EQUAL_UINT32(total - from, run.sent);                /* the pre-roll, then the rest */
        TEST_ASSERT_EQUAL_UINT32(1U, run.first_flags);
        TEST_ASSERT_EQUAL_UINT32(from, run.first_at);
        TEST_ASSERT_EQUAL_UINT32(1U, run.restore_flags);
        TEST_ASSERT_EQUAL_UINT32(at, run.restore_at);
        TEST_ASSERT_EQUAL_UINT32(1U, run.last_flags);
        TEST_ASSERT_EQUAL_UINT32(0U, run.odd_chunks);
        TEST_ASSERT_EQUAL_UINT32(output_for(total) - output_for(at), run.written);
        TEST_ASSERT_EQUAL_UINT32(output_for(total), p.out_written);     /* the whole file's count */
    }
}

/* The pre-roll's replies are not kept: none of their output is staged, so
 * nothing of it is written, and fxp_reply_kept says so for each of them. */
void test_rebuild_throws_away_the_preroll_output_and_keeps_the_rest(void)
{
    const uint32_t total = 64000U;
    const uint32_t from = 8192U;
    const uint32_t at = 12288U;
    fx_pipe_t p;
    fxp_rebuild(&p, total, from, at, output_for(at));
    pipe_run_t run;
    drive_pipe(&p, &run);
    TEST_ASSERT_TRUE(run.done);
    TEST_ASSERT_EQUAL_UINT32(output_for(total) - output_for(from), run.replied_out);   /* all of it came back */
    TEST_ASSERT_EQUAL_UINT32(output_for(total) - output_for(at), run.written);         /* only the rest is kept */
    TEST_ASSERT_EQUAL_UINT32((total - at + FXP_CHUNK_IN - 1U) / FXP_CHUNK_IN, run.kept_replies);

    /* Chunk by chunk over one read that holds both: kept exactly from the
     * chunk at `at` on; the pre-roll stages nothing. */
    const uint32_t from2 = at - 2048U;
    fxp_rebuild(&p, total, from2, at, output_for(at));
    fxp_did_read(&p, fxp_read_size(&p));
    for (uint32_t sent = from2; sent < from2 + FXP_READ_SAMPLES; sent += FXP_CHUNK_IN)
    {
        uint8_t flags = 0U;
        fxp_did_send(&p, fxp_chunk(&p, &flags));
        TEST_ASSERT_EQUAL((sent >= at), fxp_reply_kept(&p));
        fxp_did_reply(&p, FXP_CHUNK_OUT);
        const uint32_t kept_chunks = (sent >= at) ? (((sent - at) / FXP_CHUNK_IN) + 1U) : 0U;
        TEST_ASSERT_EQUAL_UINT32(kept_chunks * FXP_CHUNK_OUT, p.out_staged);
    }
}

/* From 0 the effect runs from the very first sample: its state at `at` is
 * the one-go state, so FIRST goes at 0 and no RESTORE at all. */
void test_rebuild_from_0_sends_no_restore(void)
{
    fx_pipe_t p;
    fxp_rebuild(&p, 32000U, 0U, 2560U, output_for(2560U));
    pipe_run_t run;
    drive_pipe(&p, &run);
    TEST_ASSERT_TRUE(run.done);
    TEST_ASSERT_EQUAL_UINT32(32000U, run.sent);
    TEST_ASSERT_EQUAL_UINT32(1U, run.first_flags);
    TEST_ASSERT_EQUAL_UINT32(0U, run.first_at);
    TEST_ASSERT_EQUAL_UINT32(0U, run.restore_flags);
    TEST_ASSERT_EQUAL_UINT32(output_for(32000U) - output_for(2560U), run.written);
}

/* During the pre-roll the percentage stays where the job stopped (the
 * Preparing screen shows it at once and never goes back), then climbs. A
 * rebuild at the end has nothing to do. */
void test_percent_during_a_preroll_stays_at_the_resume_point(void)
{
    const uint32_t total = 320001U;
    const uint32_t at = 160256U;
    const uint8_t at_percent = (uint8_t)(((uint64_t)at * 100U) / total);
    fx_pipe_t p;
    fxp_rebuild(&p, total, at - 8192U, at, output_for(at));
    TEST_ASSERT_EQUAL_UINT8(at_percent, fxp_percent(&p));
    TEST_ASSERT_EQUAL_UINT32(at, fxp_kept_samples(&p));
    pipe_run_t run;
    drive_pipe(&p, &run);                                   /* fails the run if the percentage drops */
    TEST_ASSERT_TRUE(run.done);
    TEST_ASSERT_FALSE(run.percent_went_down);
    TEST_ASSERT_EQUAL_UINT8(100U, run.percent_at_done);

    fxp_rebuild(&p, 32000U, 28672U, 32000U, output_for(32000U));
    TEST_ASSERT_EQUAL_UINT8(100U, fxp_percent(&p));
}

/* `from` past `at` is clamped: the rebuild then sends from `at` with FIRST
 * and RESTORE on the same chunk (FxRenderTask begins, then loads the carry). */
void test_rebuild_clamps_from_to_the_resume_point(void)
{
    fx_pipe_t p;
    fxp_rebuild(&p, 32000U, 9000U, 4096U, output_for(4096U));
    pipe_run_t run;
    drive_pipe(&p, &run);
    TEST_ASSERT_TRUE(run.done);
    TEST_ASSERT_EQUAL_UINT32(32000U - 4096U, run.sent);
    TEST_ASSERT_EQUAL_UINT32(4096U, run.first_at);
    TEST_ASSERT_EQUAL_UINT32(4096U, run.restore_at);
    TEST_ASSERT_EQUAL_UINT32(output_for(32000U) - output_for(4096U), run.written);
}

int main(void)
{
    UNITY_BEGIN();
    RUN_TEST(test_zero_samples_is_done_at_once_and_sends_nothing);
    RUN_TEST(test_one_sample_is_sent_as_the_first_and_last_chunk);
    RUN_TEST(test_exactly_one_chunk_is_one_request);
    RUN_TEST(test_one_sample_more_than_a_chunk_makes_two_chunks);
    RUN_TEST(test_a_ten_second_recording_is_sent_whole_and_written_whole);
    RUN_TEST(test_an_odd_sample_count_is_sent_whole);
    RUN_TEST(test_chunks_are_multiples_of_64_except_the_last);
    RUN_TEST(test_last_flag_is_set_once_for_every_size_above_zero);
    RUN_TEST(test_first_flag_is_set_once);
    RUN_TEST(test_writes_never_exceed_16_kb);
    RUN_TEST(test_reads_and_writes_happen_while_a_chunk_is_out);
    RUN_TEST(test_percent_climbs_to_100_and_never_drops);
    RUN_TEST(test_continue_sends_the_rest_once_with_no_first);
    RUN_TEST(test_continue_at_the_end_is_done_at_once);
    RUN_TEST(test_rebuild_sends_first_at_from_restore_once_at_the_resume_point_and_last_at_the_end);
    RUN_TEST(test_rebuild_throws_away_the_preroll_output_and_keeps_the_rest);
    RUN_TEST(test_rebuild_from_0_sends_no_restore);
    RUN_TEST(test_percent_during_a_preroll_stays_at_the_resume_point);
    RUN_TEST(test_rebuild_clamps_from_to_the_resume_point);
    return UNITY_END();
}
